/**
 * Seed data for job discovery (ADR-006: seeded jobs for dev, licensed APIs later).
 *
 * Jobs are generated by crossing role archetypes with companies and locations
 * rather than hand-writing each posting, so the set stays varied enough to
 * exercise search ranking, filters, and facets without becoming unmaintainable.
 *
 * Re-runnable: everything upserts on a stable slug.
 */
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient({ log: ['error'] });

type Seniority = 'intern' | 'junior' | 'mid' | 'senior' | 'lead' | 'principal';

interface CompanySeed {
  name: string;
  slug: string;
  industry: string;
  size: string;
  location: string;
  websiteUrl: string;
  about: string;
}

interface RoleTemplate {
  key: string;
  title: string;
  family: string;
  skills: string[];
  summary: string;
  responsibilities: string[];
  requirements: string[];
  /** Mid-level base salary in USD; other seniorities scale from this. */
  baseSalary: number;
  seniorities: Seniority[];
}

