const SENIORITY_PREFIX: Record<Seniority, string> = {
  intern: 'Intern',
  junior: 'Junior',
  mid: '',
  senior: 'Senior',
  lead: 'Lead',
  principal: 'Principal',
};

const SENIORITY_MULTIPLIER: Record<Seniority, number> = {
  intern: 0.35,
  junior: 0.72,
  mid: 1,
  senior: 1.3,
  lead: 1.55,
  principal: 1.8,
};

const SENIORITY_YEARS: Record<Seniority, string> = {
  intern: 'currently studying toward a relevant degree',
  junior: 'around 1-2 years of professional experience',
  mid: '3-5 years of professional experience',
  senior: '5-8 years of professional experience',
  lead: '8+ years of experience including technical leadership',
  principal: '10+ years of experience setting technical direction',
};

const EMPLOYMENT_TYPES = ['full-time', 'full-time', 'full-time', 'contract', 'part-time'];

const BENEFITS = [
  'Private health, dental, and vision cover',
  'Annual learning budget and conference allowance',
  'Home office stipend',
  'Flexible working hours across time zones',
  'Equity participation',
  'Paid parental leave',
  'Four weeks paid holiday plus public holidays',
];

/** Deterministic pseudo-random so re-seeding produces identical data. */
function hash(input: string): number {
  let h = 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

function pick<T>(items: T[], key: string, offset = 0): T {
  return items[(hash(key) + offset) % items.length];
}

function roundTo(value: number, step: number): number {
  return Math.round(value / step) * step;
}

function buildDescription(role: RoleTemplate, company: CompanySeed, seniority: Seniority): string {
  return [
    `${company.name} is hiring a ${SENIORITY_PREFIX[seniority] ? `${SENIORITY_PREFIX[seniority]} ` : ''}${role.title} to join our ${role.family} team.`,
    '',
    role.summary,
    '',
    `About ${company.name}: ${company.about}`,
    '',
    `We are looking for someone with ${SENIORITY_YEARS[seniority]}. We review every application ourselves and aim to respond within a week.`,
  ].join('\n');
}

async function main() {
  const companies = new Map<string, string>();

  for (const company of COMPANIES) {
    const record = await prisma.company.upsert({
      where: { slug: company.slug },
      update: {
        name: company.name,
        industry: company.industry,
        size: company.size,
        location: company.location,
        websiteUrl: company.websiteUrl,
        about: company.about,
      },
      create: company,
    });
    companies.set(company.slug, record.id);
  }

  console.log(`seeded ${companies.size} companies`);

  let created = 0;
  let updated = 0;
  const now = Date.now();

  for (const role of ROLES) {
    for (const seniority of role.seniorities) {
      // Spread each role across a few companies so filters return varied results.
      const companyCount = seniority === 'mid' || seniority === 'senior' ? 2 : 1;

      for (let n = 0; n < companyCount; n += 1) {
        const company = pick(COMPANIES, `${role.key}:${seniority}`, n * 3);
        const place = pick(LOCATIONS, `${role.key}:${seniority}:${company.slug}`, n);
        const employmentType = pick(EMPLOYMENT_TYPES, `${role.key}:${company.slug}:${seniority}`);

        const prefix = SENIORITY_PREFIX[seniority];
        const title = prefix ? `${prefix} ${role.title}` : role.title;
        const slug = `${company.slug}-${seniority}-${role.key}-${n}`;

        const midpoint = role.baseSalary * SENIORITY_MULTIPLIER[seniority];
        const salaryMin = roundTo(midpoint * 0.9, 1000);
        const salaryMax = roundTo(midpoint * 1.2, 1000);

        // Stagger posting dates over the last six weeks so "recent" sorting is meaningful.
        const daysAgo = hash(slug) % 42;
        const postedAt = new Date(now - daysAgo * 24 * 60 * 60 * 1000);

        const benefitCount = 3 + (hash(slug) % 3);
        const benefits = BENEFITS.slice(0, benefitCount);

        const data = {
          companyId: companies.get(company.slug)!,
          title,
          description: buildDescription(role, company, seniority),
          responsibilities: role.responsibilities,
          requirements: [...role.requirements, `We expect ${SENIORITY_YEARS[seniority]}.`],
          benefits,
          skills: role.skills,
          employmentType,
          workMode: place.workMode,
          seniority,
          location: place.location,
          city: place.city,
          country: place.country,
          salaryMin,
          salaryMax,
          salaryCurrency: 'USD',
          salaryPeriod: 'year',
          source: 'seed',
          externalId: slug,
          applyUrl: `${company.websiteUrl}/careers/${slug}`,
          postedAt,
          isActive: true,
        };

        const existing = await prisma.job.findUnique({ where: { slug }, select: { id: true } });

        if (existing) {
          await prisma.job.update({ where: { slug }, data });
          updated += 1;
        } else {
          await prisma.job.create({ data: { ...data, slug } });
          created += 1;
        }
      }
    }
  }

  console.log(`seeded jobs: ${created} created, ${updated} updated`);

  // Content changed, so any existing embeddings are stale.
  const reset = await prisma.job.updateMany({
    where: { source: 'seed' },
    data: { embeddingStatus: 'idle', embeddingError: null },
  });
  console.log(`marked ${reset.count} jobs for re-embedding`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
